/**
 * Counts the number of words in a given string.
 * Words are defined as sequences of non-whitespace characters separated by whitespace.
 *
 * @param {string} text The input string to analyze.
 * @returns {number} The total number of words in the string. Returns 0 if the input is null, undefined, or empty.
 */
function countWords(text) {
  // 1. Handle edge cases: null, undefined, or non-string input
  if (typeof text !== 'string' || text.trim() === '') {
    return 0;
  }

  // 2. Use a regular expression to split the string by one or more whitespace characters (\s+).
  // The .filter(Boolean) step removes any empty strings that might result from leading/trailing
  // whitespace or multiple spaces between words.
  const words = text.trim().split(/\s+/).filter(word => word.length > 0);

  // 3. Return the length of the resulting array
  return words.length;
}

// --- Examples ---

