Here is a JavaScript function that formats a number as a currency string.

This implementation uses `Intl.NumberFormat` which is the modern and recommended way to handle locale-aware number and currency formatting in JavaScript.

```javascript
/**
 * Formats a number as a currency string based on a specified locale.
 *
 * @param {number} amount The number to format.
 * @param {string} currencyCode The ISO 4217 currency code (e.g., 'USD', 'EUR', 'JPY').
 * @param {string} locale The locale to use for formatting (e.g., 'en-US', 'de-DE').
 * @returns {string} The formatted currency string.
 * @throws {Error} If the amount is not a finite number or if the locale or currency code is invalid.
 */
function formatCurrency(amount, currencyCode, locale) {
    if (typeof amount !== 'number' || !isFinite(amount)) {
        throw new Error("The first argument must be a finite number.");
    }
    if (typeof currencyCode !== 'string' || currencyCode.length === 0) {
        throw new Error("The currencyCode must be a non-empty string.");
    }
    if (typeof locale !== 'string' || locale.length === 0) {
        throw new Error("The locale must be a non-empty string.");
    }

    try {
        // Create a formatter instance using the Intl API
        const formatter = new Intl.NumberFormat(locale, {
            style: 'currency',
            currency: currencyCode,
        });

        // Format the number
        return formatter.format(amount);
    } catch (error) {
        // Catch errors thrown by Intl.NumberFormat (e.g., invalid currency code)
        console.error(`Error formatting currency: ${error.message}`);
        throw new Error(`Failed to format currency. Check locale or currency code: ${error.message}`);
    }
}

