/**
 * Creates a throttled version of a function that only invokes it at most once
 * per every wait milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to wait between invocations.
 * @returns {Function} A new function that throttles the original function.
 */
function throttle(func, wait) {
  let timeout = null;
  let lastArgs = null;
  let lastThis = null;
  let lastExecTime = 0;

  return function(...args) {
    const context = this;
    const now = Date.now();

    // If it's the first call or enough time has passed since the last execution
    if (now - lastExecTime >= wait) {
      lastExecTime = now;
      func.apply(context, args);
    } else {
      // If it's within the wait period, we store the latest arguments
      // to be executed after the wait period is over.
      lastArgs = args;
      lastThis = context;

      // If there isn't an existing timeout, set one to execute the function
      // after the wait period. This ensures that if calls happen rapidly,
      // only the *last* call within the burst is executed after the delay.
      if (!timeout) {
        timeout = setTimeout(() => {
          lastExecTime = Date.now();
          timeout = null;
          // Execute the function with the last recorded arguments and context
          func.apply(lastThis, lastArgs);
          lastArgs = null;
          lastThis = null;
        }, wait - (now - lastExecTime)); // Calculate remaining time for better accuracy
      }
    }
  };
}

