Here is a TypeScript function that merges two sorted arrays into a single sorted array.

This implementation uses the standard two-pointer approach, which is efficient (time complexity $O(n+m)$ where $n$ and $m$ are the lengths of the arrays).

```typescript
/**
 * Merges two sorted arrays into a single sorted array.
 *
 * @param arr1 The first sorted array.
 * @param arr2 The second sorted array.
 * @returns A new array containing all elements from arr1 and arr2, sorted.
 */
function mergeSortedArrays<T>(arr1: T[], arr2: T[]): T[] {
    const mergedArray: T[] = [];
    let i = 0; // Pointer for arr1
    let j = 0; // Pointer for arr2

    // While both arrays have elements to compare
    while (i < arr1.length && j < arr2.length) {
        if (arr1[i] <= arr2[j]) {
            mergedArray.push(arr1[i]);
            i++;
        } else {
            mergedArray.push(arr2[j]);
            j++;
        }
    }

    // Add any remaining elements from arr1
    while (i < arr1.length) {
        mergedArray.push(arr1[i]);
        i++;
    }

    // Add any remaining elements from arr2
    while (j < arr2.length) {
        mergedArray.push(arr2[j]);
        j++;
    }

    return mergedArray;
}

// --- Example Usage ---

// Example 1: Merging arrays of numbers
const sortedNumbers1: number[] = [1, 3, 5, 7];
const sortedNumbers2: number[] = [2, 4, 6, 8, 10];
const mergedNumbers: number[] = mergeSortedArrays(sortedNumbers1, sortedNumbers2);

console.log("Merged Numbers:", mergedNumbers); // Output: [1, 2, 3, 4, 5, 6, 7, 8, 10]

// Example 2: Merging arrays of strings
