  console.log(`Attempting to fetch data from: ${mockApiUrl}`);
  try {
    const result: any = await fetchJsonData(mockApiUrl);
    console.log("\n--- Successfully Fetched Data ---");
    console.log(result);
    console.log("---------------------------------");
  } catch (error) {
    console.error("\n--- Operation Failed ---");
    console.error("Could not complete the data fetching operation.");
  }
}

main();
```

