Here is a TypeScript function that converts a snake\_case string to camelCase.

This implementation handles cases where the input might start with an uppercase letter (like in PascalCase or if the first word is capitalized) by ensuring the very first word remains lowercase, which is the standard for camelCase.

```typescript
/**
 * Converts a snake_case string to camelCase.
 *
 * @param snakeCaseString The input string in snake_case format (e.g., "hello_world_example").
 * @returns The converted string in camelCase format (e.g., "helloWorldExample").
 */
function snakeToCamel(snakeCaseString: string): string {
  if (!snakeCaseString) {
    return "";
  }

  // Split the string by the underscore character
  const parts: string[] = snakeCaseString.split('_');

  if (parts.length === 0) {
    return "";
  }

  // The first part remains as is (or lowercased if we strictly enforce camelCase start)
  let camelCaseString: string = parts[0];

  // Iterate over the rest of the parts and capitalize the first letter of each
  for (let i = 1; i < parts.length; i++) {
    const part = parts[i];
    if (part.length > 0) {
      // Capitalize the first letter and append the rest of the string in lowercase
      const capitalizedPart = part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
      camelCaseString += capitalizedPart;
    }
  }

  return camelCaseString;
}

// --- Examples ---

const example1 = "hello_world_example";
console.log(`Input: ${example1} -> Output: ${snakeToCamel(example1)}`); // Output: helloWorldExample

const example2 = "user_id_details";
console.log(`Input: ${example2} -> Output: ${snakeToCamel(example2)}`); // Output: userIdDetails

const example3 = "singleword";
console.log(`Input: ${example3} -> Output: ${snakeToCamel(example3)}`); // Output: singleword

const example4 = "";
console.log(`Input: "${example4}" -> Output: "${snakeToCamel(example4)}"`); // Output: ""

const example5 = "_leading_underscore";
console.log(`Input: ${example5} -> Output: ${snakeToCamel(example5)}`); // Output: LeadingUnderscore (Note: the first part is empty, handled by the logic)

const example6 = "alreadyCamel";
console.log(`Input: ${example6} -> Output: ${snakeToCamel(example6)}`); // Output: alreadyCamel (No underscores, returns as is)
```

Here is a TypeScript function that checks whether the parentheses in a string are balanced. This implementation handles three types of parentheses: `()`, `[]`, and `{}`.

```typescript
/**
 * Checks if the parentheses in a given string are balanced.
 *
 * @param str The input string to check.
 * @returns True if the parentheses are balanced, false otherwise.
 */
function areParenthesesBalanced(str: string): boolean {
    const stack: string[] = [];
    const map: { [key: string]: string } = {
        ')': '(',
        ']': '[',
        '}': '{'
    };

    for (const char of str) {
        // If the character is an opening bracket, push it onto the stack.
        if (char === '(' || char === '[' || char === '{') {
            stack.push(char);
        } 
        // If the character is a closing bracket.
        else if (char === ')' || char === ']' || char === '}') {
            // If the stack is empty, we have a closing bracket without a corresponding opener.
            if (stack.length === 0) {
                return false;
            }

            // Pop the last opening bracket from the stack.
            const lastOpen = stack.pop();

            // Check if the popped opening bracket matches the current closing bracket.
            if (lastOpen !== map[char]) {
                return false;
            }
        }
        // Ignore any other characters in the string.
    }

    // After iterating through the entire string, the stack must be empty for the parentheses to be balanced.
    return stack.length === 0;
}

