/**
 * Formats a Date object into a 'YYYY-MM-DD' string format.
 *
 * @param date The Date object to format.
 * @returns A string representing the date in 'YYYY-MM-DD' format, or an error message if the date is invalid.
 */
function formatDateToYYYYMMDD(date: Date): string {
  // Check if the input is a valid Date object
  if (!(date instanceof Date) || isNaN(date.getTime())) {
    return "Invalid Date";
  }

  // Get year, month, and day
  const year: number = date.getFullYear();
  // getMonth() is 0-indexed, so we add 1
  const month: number = date.getMonth() + 1;
  const day: number = date.getDate();

  // Helper function to pad single-digit numbers with a leading zero
  const pad = (num: number): string => {
    return num.toString().padStart(2, '0');
  };

  const formattedYear: string = year.toString();
  const formattedMonth: string = pad(month).toString();
  const formattedDay: string = pad(day).toString();

  return `${formattedYear}-${formattedMonth}-${formattedDay}`;
}

// --- Example Usage ---

