 */
void swap_integers(int *a, int *b) {
    // Create a temporary variable to hold the value of the first integer
    int temp = *a;

    // Assign the value pointed to by 'b' to the location pointed to by 'a'
    *a = *b;

    // Assign the temporary value (original *a) to the location pointed to by 'b'
    *b = temp;
