    int y = 20;

    printf("Before swapping: x = %d, y = %d\n", x, y);

    // Call the swap function, passing the addresses of x and y
    swap_integers(&x, &y);

    printf("After swapping: x = %d, y = %d\n", x, y);

    return 0;
}
