```rust
/// Finds the largest element in a slice of i32.
///
/// Returns `Some(i32)` containing the largest element if the slice is not empty,
/// or `None` if the slice is empty.
///
/// # Arguments
///
/// * `slice` - A slice of i32 values to search through.
///
/// # Examples
///
/// ```
/// let data1 = vec![1, 5, 2, 9, 3];
/// assert_eq!(find_largest(&data1), Some(9));
///
/// let data2: Vec<i32> = vec![];
/// assert_eq!(find_largest(&data2), None);
///
/// let data3 = vec![-10, -5, -1];
/// assert_eq!(find_largest(&data3), Some(-1));
/// ```
pub fn find_largest(slice: &[i32]) -> Option<i32> {
    // If the slice is empty, there is no largest element, so return None.
    if slice.is_empty() {
        return None;
    }

    // Initialize the maximum value with the first element of the slice.
    let mut largest = slice[0];

    // Iterate over the rest of the elements (starting from the second element).
    for &item in slice.iter().skip(1) {
        if item > largest {
            largest = item;
        }
    }

    // Return the largest element found.
    Some(largest)
}

// A slightly more idiomatic alternative using the `iter().max()` method,
// which is often preferred in Rust for finding maximums/minimums.
pub fn find_largest_idiomatic(slice: &[i32]) -> Option<i32> {
    slice.iter().cloned().max()
}

fn main() {
    let data1 = vec![1, 5, 2, 9, 3];
    println!("Largest in {:?}: {:?}", data1, find_largest(&data1)); // Output: Some(9)

    let data2: Vec<i32> = vec![];
    println!("Largest in empty slice: {:?}", find_largest(&data2)); // Output: None

    let data3 = vec![-10, -5, -1];
    println!("Largest in {:?}: {:?}", data3, find_largest(&data3)); // Output: Some(-1)

    println!("--- Idiomatic Check ---");
    println!("Largest in {:?}: {:?}", data1, find_largest_idiomatic(&data1)); // Output: Some(9)
}
